SELECT c.contract_result_id,c.contract_date,c.contract_name,c.contract_institution_name,c.target_detailed_product_class_no,COALESCE((SELECT product_class_name||CASE WHEN count(*)>1 THEN ' 외 '||(count(*)-1)||'건' ELSE '' END FROM contract_item i JOIN contract_search_headers h ON h.contract_header_id=i.contract_header_id WHERE h.decision_contract_no=c.decision_contract_no),''),COALESCE((SELECT CASE WHEN count(DISTINCT COALESCE(sc.cmpnt_yn,cat.cmpnt_yn))=1 THEN CASE min(COALESCE(sc.cmpnt_yn,cat.cmpnt_yn)) WHEN 'Y' THEN 'part' WHEN 'N' THEN 'product' END WHEN count(DISTINCT COALESCE(sc.cmpnt_yn,cat.cmpnt_yn))>1 THEN 'mixed' END FROM search_classes sc LEFT JOIN catalog_item_category cat ON cat.prdct_idnt_no=sc.product_id WHERE sc.domain='CONTRACT' AND sc.source_id=c.contract_result_id),'unknown'),(SELECT corporation_name||CASE WHEN (SELECT count(*) FROM contract_corporation x WHERE x.contract_result_id=c.contract_result_id)>1 THEN ' 외 '||((SELECT count(*) FROM contract_corporation x WHERE x.contract_result_id=c.contract_result_id)-1)||'개' ELSE '' END FROM contract_corporation x WHERE x.contract_result_id=c.contract_result_id ORDER BY CASE role_name WHEN '주계약업체' THEN 0 ELSE 1 END,sequence_no LIMIT 1),NULL,c.contract_method_name,c.contract_name,c.contract_amount,0,0,1,'UNLINKED' FROM contract_result c WHERE (?1='' OR c.contract_name LIKE ?2 OR c.contract_institution_name LIKE ?2 OR c.demand_institution_name LIKE ?2 OR c.decision_contract_no LIKE ?2 OR c.target_detailed_product_class_no LIKE ?2 OR EXISTS(SELECT 1 FROM search_classes sc WHERE sc.domain='CONTRACT' AND sc.source_id=c.contract_result_id AND (sc.classification_no LIKE ?2 OR sc.detailed_no LIKE ?2 OR sc.product_id LIKE ?2 OR sc.classification_name LIKE ?2 OR sc.detailed_name LIKE ?2)) OR EXISTS(SELECT 1 FROM contract_corporation x WHERE x.contract_result_id=c.contract_result_id AND x.corporation_name LIKE ?2)) AND (?3='all' OR EXISTS(SELECT 1 FROM search_classes sc LEFT JOIN catalog_item_category cat ON cat.prdct_idnt_no=sc.product_id WHERE sc.domain='CONTRACT' AND sc.source_id=c.contract_result_id AND CASE COALESCE(sc.cmpnt_yn,cat.cmpnt_yn) WHEN 'Y' THEN 'part' WHEN 'N' THEN 'product' END=?3)) ORDER BY c.contract_date DESC,c.contract_result_id DESC LIMIT ?4